-- 218: Original BrillaPrep WASSCE BrillaPrep transitional Sculpture beta content blueprint questions, part 6.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_218_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_218_guard;
INSERT INTO _migration_218_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_021' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_5' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the indirect method of producing a sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The artist studies a reference but never makes an intermediate form","B. The final material is shaped directly without a model or transfer stage","C. A model is made first and transferred through a mould, pointing or other intermediate process into the final material","D. Found objects are displayed unchanged without joining or replication"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Indirect production separates the original model from the final material. Moulding and casting, enlargement from a maquette, or point-transfer carving can preserve and translate the designed form. Therefore the correct answer is C: A model is made first and transferred through a mould, pointing or other intermediate process into the final material.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_021' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_218_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_022' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_5' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why can a deep undercut prevent release from a rigid one-piece mould?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The undercut makes the mould material too absorbent to set","B. The casting becomes larger only because the mould has one section","C. The mould locks mechanically behind the projecting form","D. The parting line becomes visible even though no mould division exists"]' AND q.correct_answer IS 'C' AND q.explanation IS 'If the form widens behind the mould opening, a rigid shell cannot withdraw along one direction. Planned sections, flexible mould material or modification of the form are required. Therefore the correct answer is C: The mould locks mechanically behind the projecting form.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_022' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_218_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_023' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_5' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What determines a suitable dividing line for a two-part mould?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The line should cross the most prominent feature regardless of the seam","B. Each section can withdraw cleanly while important detail and registration are preserved","C. The division can be chosen after the first rigid half encloses the model","D. Both halves should contain the same number of undercuts"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A good parting line balances release geometry, seam placement, mould strength and accurate reassembly. Registration keys help the sections return to the same relationship for casting. Therefore the correct answer is B: Each section can withdraw cleanly while important detail and registration are preserved.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_023' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_218_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_024' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_5' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What are the functions of a pouring sprue and vents in a closed mould?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Use one low sprue without separate vents because trapped air will return through the incoming material stream","B. Use the upper vents as inlets and keep the lower sprue mainly as a reservoir that feeds shrinkage after the pour","C. The sprue admits casting material while vents allow displaced air and gases to escape","D. Make the sprue and vents the same diameter so liquid and displaced air can circulate through either channel during filling"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Casting material must enter continuously as air leaves the cavity. Correct gate size, sprue placement and vents at likely high points reduce bubbles, short fills and turbulent flow marks. Therefore the correct answer is C: The sprue admits casting material while vents allow displaced air and gases to escape.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_024' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_021', 'topic_was_sculpture_b004_5', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What is the indirect method of producing a sculpture?', 'multiple_choice', NULL, '["A. The artist studies a reference but never makes an intermediate form","B. The final material is shaped directly without a model or transfer stage","C. A model is made first and transferred through a mould, pointing or other intermediate process into the final material","D. Found objects are displayed unchanged without joining or replication"]', 'C', 'Indirect production separates the original model from the final material. Moulding and casting, enlargement from a maquette, or point-transfer carving can preserve and translate the designed form. Therefore the correct answer is C: A model is made first and transferred through a mould, pointing or other intermediate process into the final material.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_5', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_022', 'topic_was_sculpture_b004_5', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Why can a deep undercut prevent release from a rigid one-piece mould?', 'multiple_choice', NULL, '["A. The undercut makes the mould material too absorbent to set","B. The casting becomes larger only because the mould has one section","C. The mould locks mechanically behind the projecting form","D. The parting line becomes visible even though no mould division exists"]', 'C', 'If the form widens behind the mould opening, a rigid shell cannot withdraw along one direction. Planned sections, flexible mould material or modification of the form are required. Therefore the correct answer is C: The mould locks mechanically behind the projecting form.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_5', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_023', 'topic_was_sculpture_b004_5', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What determines a suitable dividing line for a two-part mould?', 'multiple_choice', NULL, '["A. The line should cross the most prominent feature regardless of the seam","B. Each section can withdraw cleanly while important detail and registration are preserved","C. The division can be chosen after the first rigid half encloses the model","D. Both halves should contain the same number of undercuts"]', 'B', 'A good parting line balances release geometry, seam placement, mould strength and accurate reassembly. Registration keys help the sections return to the same relationship for casting. Therefore the correct answer is B: Each section can withdraw cleanly while important detail and registration are preserved.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_5', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_024', 'topic_was_sculpture_b004_5', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What are the functions of a pouring sprue and vents in a closed mould?', 'multiple_choice', NULL, '["A. Use one low sprue without separate vents because trapped air will return through the incoming material stream","B. Use the upper vents as inlets and keep the lower sprue mainly as a reservoir that feeds shrinkage after the pour","C. The sprue admits casting material while vents allow displaced air and gases to escape","D. Make the sprue and vents the same diameter so liquid and displaced air can circulate through either channel during filling"]', 'C', 'Casting material must enter continuously as air leaves the cavity. Correct gate size, sprue placement and vents at likely high points reduce bubbles, short fills and turbulent flow marks. Therefore the correct answer is C: The sprue admits casting material while vents allow displaced air and gases to escape.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_5', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_sculpture_b004_021', 'q_was_sculpture_b004_022', 'q_was_sculpture_b004_023', 'q_was_sculpture_b004_024');
